// GET /produtos?page=0&size=20&sort=preco,desc&categoria=livros
@GetMapping("/produtos")
public Page<ProdutoResponse> listar(@RequestParam(required = false) String categoria,
                                    @PageableDefault(size = 20) Pageable pageable) {
    return repository.findByCategoria(categoria, pageable)
                     .map(ProdutoResponse::from);
}

@RestControllerAdvice
public class ApiExceptionHandler {
    @ExceptionHandler(PedidoNaoEncontradoException.class)
    ProblemDetail naoEncontrado(PedidoNaoEncontradoException ex) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
        pd.setTitle("Pedido não encontrado");
        return pd;
    }
}

// Resposta (application/problem+json):
